using ChartForgeX.Interactivity.Html;
using ChartForgeX.Typography;
internal static class NativeScatterValueExamples {
    internal static void Write(string output,string[] args){var font=NativeFallbackRadialExamples.RequiredFont(args,"--primary-font");FontRegistry.Register("Owned scatter font",font);Directory.CreateDirectory(output);var renderer=new HtmlInteractiveChartRenderer();foreach(var initial in new[]{false,true})foreach(var width in new[]{390,760}){var mode=width==390?VisualThemeMode.Light:VisualThemeMode.Dark;var from=renderer.PrepareSection(NativeOwnedValueFlashRecipe.Create("scatter",30,width,mode,"Owned scatter font"));var to=renderer.PrepareSection(NativeOwnedValueFlashRecipe.Create("scatter",40,width,mode,"Owned scatter font"));var payload=renderer.PrepareNativeTransitionJson(from,to,new HtmlNativeTransitionOptions(initial?HtmlNativeTransitionEffect.InitialValues:HtmlNativeTransitionEffect.Values,5));var prefix=Path.Combine(output,"native-scatter-"+initial+"-"+width);File.WriteAllText(prefix+".from.html",from.Html);File.WriteAllText(prefix+".to.html",to.Html);File.WriteAllText(prefix+".transition.json",payload);File.WriteAllText(prefix+".from.svg",from.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".from.png",from.PreparedVisual.ToPng());File.WriteAllText(prefix+".to.svg",to.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".to.png",to.PreparedVisual.ToPng());File.WriteAllText(prefix+".program.cs",ExampleRecipeSource.EmitNativeScatterValue(initial,width,mode));}}
}
